import pytest

from bedrock_protocol import v975, v1001

versions = [v975, v1001]

# generated by gophertunnel 6353c49:
# packet.PacketViolationWarning{Type: packet.ViolationTypeMalformed,
# Severity: packet.ViolationSeverityTerminatingConnection,
# PacketID: 30, ViolationContext: "malformed packet"}
TERMINATING = bytes.fromhex("00043c106d616c666f726d6564207061636b6574")

# generated by gophertunnel 6353c49:
# packet.PacketViolationWarning{Type: -1, Severity: -1, PacketID: 156, ViolationContext: ""}
UNKNOWN = bytes.fromhex("0101b80200")

GOLDENS = [
    *[
        pytest.param(
            version.PacketViolationWarningPacket(
                violation_type=version.PacketViolationType.PACKET_MALFORMED,
                violation_severity=version.PacketViolationSeverity.TERMINATING_CONNECTION,
                violating_packet_id=version.MinecraftPacketIds.INVENTORY_TRANSACTION,
                violation_context="malformed packet",
            ),
            TERMINATING,
            id=f"{version.__name__.rpartition('.')[2]}-terminating",
        )
        for version in versions
    ],
    *[
        pytest.param(
            version.PacketViolationWarningPacket(
                violation_type=version.PacketViolationType.UNKNOWN,
                violation_severity=version.PacketViolationSeverity.UNKNOWN,
                violating_packet_id=version.MinecraftPacketIds.PACKET_VIOLATION_WARNING,
                violation_context="",
            ),
            UNKNOWN,
            id=f"{version.__name__.rpartition('.')[2]}-unknown",
        )
        for version in versions
    ],
]


@pytest.mark.parametrize("version", versions)
def test_packet_violation_warning_is_packet_156(version):
    assert version.packets[156] is version.PacketViolationWarningPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_packet_violation_warning_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_packet_violation_warning_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize("version", versions)
def test_packet_violation_warning_rejects_a_truncated_context(version):
    with pytest.raises(ValueError, match="at byte"):
        version.PacketViolationWarningPacket.from_bytes(TERMINATING[:-1])
